LAINNYA = 'Lainnya'


def pindahkan_ke_lainnya(apps, schema_editor):
    Asset = apps.get_model('bibasset', 'Asset')
    AssetCategory = apps.get_model('bibasset', 'AssetCategory')
    for group_id in (Asset.objects.filter(asset_group__isnull=False, asset_category__isnull=True)
                     .values_list('asset_group_id', flat=True).distinct()):
        # Interval maintenance kosong: aset ini memang belum punya jadwal otomatis sebelumnya
        cat, _ = AssetCategory.objects.get_or_create(group_id=group_id, name=LAINNYA)
        Asset.objects.filter(asset_group_id=group_id, asset_category__isnull=True).update(asset_category=cat)


def isi_ulang_grup(apps, schema_editor):
    """Rollback: kolom asset_group diisi lagi dari kategorinya (kategori 'Lainnya' dibiarkan)."""
    Asset = apps.get_model('bibasset', 'Asset')
    for a in Asset.objects.filter(asset_category__isnull=False).select_related('asset_category'):
        Asset.objects.filter(pk=a.pk).update(asset_group_id=a.asset_category.group_id)


def samakan_pemegang(apps, schema_editor):
    """Assignment aktif mengikuti AssetMovement.held_by terkini (logika yang sama dengan sync_holder)."""
    AssetMovement = apps.get_model('bibasset', 'AssetMovement')
    AssetAssignment = apps.get_model('bibasset', 'AssetAssignment')
    for mv in AssetMovement.objects.filter(is_current=True):
        tanggal = timezone.localdate(mv.moved_in)
        aktif = list(AssetAssignment.objects.filter(asset_id=mv.asset_id, status='active').order_by('-assigned_date', '-id'))
        if len(aktif) == 1 and aktif[0].assigned_to_id == mv.held_by_id:
            continue
        for a in aktif:
            a.status = 'transferred' if mv.held_by_id else 'returned'
            a.returned_date = tanggal
            a.save(update_fields=['status', 'returned_date'])
        if mv.held_by_id:
            AssetAssignment.objects.create(
                asset_id=mv.asset_id, assigned_to_id=mv.held_by_id, assigned_by_id=mv.recorded_by_id,
                assigned_date=tanggal, status='active',
                notes='Disinkronkan dari riwayat movement (serah terima belum tercatat).',
            )


